// [Blur2PC][macOS] Actual original reduced/postprocess allocation contracts on real Metal storage.
#include <core/Core.h>
#include <core/Maths.h>
#include <display.h>
#include <render/reducedrender/Manager.h>
#include <render/postprocess/Manager.h>
#include <cstring>
#include <iostream>
#include <stdexcept>
static void require(bool value,const char* why){if(!value){std::cerr<<why<<std::endl;throw std::runtime_error(why);}}
static void pixels(const Display::C_Texture& texture,bool floating){auto lock=texture.LockRect2D(0,16);require(lock.pBits,"Original postprocess GPU output unavailable");bool correct=true;for(U32 y=0;y<texture.GetHeight();++y)for(U32 x=0;x<texture.GetWidth();++x){if(floating){U16 actual[4];std::memcpy(actual,lock.pBits+y*lock.pitch+x*8,8);correct&=actual[0]==0&&actual[1]==0&&actual[2]==0x3c00&&actual[3]==0x3c00;}else{U32 actual;std::memcpy(&actual,lock.pBits+y*lock.pitch+x*4,4);correct&=actual==0xff0000ff;}}texture.UnlockRect2D(0);require(correct,"Original reduced/postprocess GPU clear or read/write slot storage mismatch");}
int main(){try{
    Display::C_Device device;Display::C_DeviceParams params;params.m_Width=64;params.m_Height=48;require(device.Create(params)&&device.CreateVolatile(params),"Original postprocess allocation fixture device failed");
    auto clear=[&](const Display::C_Surface* colour,const Display::C_Surface* depth){require(device.BeginScene(),"Original allocation GPU scene failed");device.SetColourDepthStencilSurface(colour,depth);device.GetDisplay2().GetContext().SetViewport(Display2::C_Viewport(0,0,colour->GetWidth(),colour->GetHeight()));device.GetDisplay2().GetContext().Clear(Display2::E_Clear_Colour|(depth?Display2::E_Clear_Depth|Display2::E_Clear_Stencil:0),0xff0000ff,.5f,0x7a);device.SetColourDepthStencilSurface();device.EndScene();};
    for(bool floating:{false,true}){Render::Reduced::C_Manager reduced(floating);reduced.AddView(0,64,48);reduced.AddView(1,64,48);require(reduced.OnCreateVolatile(),"Original ReducedRender volatile allocation failed");for(auto down:{Render::Reduced::E_Downsample_Quarter,Render::Reduced::E_Downsample_Sixteenth}){const U32 scale=down==Render::Reduced::E_Downsample_Quarter?2:4;auto* colour=reduced.GetColourSurface(0,down);auto* depth=reduced.GetDepthStencilSurface(0,down);require(colour&&depth&&colour->GetWidth()==64/scale&&colour->GetHeight()==48/scale&&depth->GetFormat()==Display2::E_SurfaceFormat_D24S8&&depth->GetWidth()==colour->GetWidth()&&depth->GetHeight()==colour->GetHeight(),"Original reduced target PC depth/colour metadata mismatch");require(colour==reduced.GetColourSurface(1,down)&&depth==reduced.GetDepthStencilSurface(1,down),"Original reduced duplicate view mapping did not share its actual targets");clear(colour,depth);pixels(*reduced.GetTexture(0,down),floating);}reduced.OnDestroyVolatile();}
    for(bool floating:{false,true}){PostProcess::C_Manager post;post.ReserveView(64,48);require(post.AddView(64,48,0,floating?PostProcess::E_RenderTargetFormat_RGBA_F10:PostProcess::E_RenderTargetFormat_RGBA_U8,Display::E_Multisample_None,3),"Original postprocess view setup failed");require(post.OnCreateVolatile(),"Original postprocess primary/downsample/depth allocation failed");require(post.GetRenderTargetCount()==1,"Original postprocess actual target count wrong");const auto& target=post.GetRenderTarget(0);require(target.m_RenderTextures.Size()==4&&target.m_pDepthStencilSurface->GetFormat()==Display2::E_SurfaceFormat_D24S8,"Original postprocess target chain or depth format wrong");for(U32 i=0;i<4;++i){auto* texture=target.m_RenderTextures[i];require(texture->GetTexture().GetWidth()==64/(1U<<i)&&texture->GetTexture().GetHeight()==48/(1U<<i),"Original postprocess downsample dimension mismatch");clear(&texture->GetSurface(),i?nullptr:target.m_pDepthStencilSurface);texture->Resolve();pixels(texture->GetTexture(),floating&&!i);}
        PostProcess::RenderTextures users;const U32 flags=Display::E_Usage_Colour|Display::E_Usage_ReadWrite,budget=post.GetMaximumTextureSize(2,2);require(budget>0&&post.CreateUserRenderTextures(2,2,flags,Display::E_Format_Unknown,nullptr,users,nullptr,budget)&&users.Size()==1,"Original PC postprocess null overlap address/nonzero calculated size rejected");auto* user=users[0];require(user->GetTexture().GetWidth()==32&&user->GetTexture().GetHeight()==24,"Original effect user allocation dimensions wrong");clear(&user->GetSurface(),nullptr);user->Resolve();pixels(user->GetTexture(),floating);auto oldRead=user->GetTexture();clear(&user->GetSurface(),nullptr);user->Resolve();pixels(user->GetTexture(),floating);require(user->GetTexture().IsCreated()&&oldRead.IsCreated(),"Original PC read/write allocation lost independently owned GPU slots");post.DestroyUserRenderTextures(users);oldRead=Display::C_Texture{};post.OnDestroyVolatile();}
    Display::C_RenderTexture2D rejected;U8 storage=0;require(!device.CreateRenderTexture2D(8,8,1,Display::E_Usage_Colour,Display::E_Format_A8R8G8B8,Display::E_Multisample_None,nullptr,&rejected,&storage,256)&&!rejected.IsCreated(),"Native external-memory alias request falsely reported support");require(!device.CreateRenderTexture2D(0,8,1,Display::E_Usage_Colour,Display::E_Format_A8R8G8B8,Display::E_Multisample_None,nullptr,&rejected,nullptr,256)&&!rejected.IsCreated(),"Native null-memory budget bypassed real GPU dimension validation");
    require(device.GetDisplay2().WaitIdle(),"Original allocation fixture GPU completion failed");
#if TRACK_DISPLAY2_RESOURCES
    require(device.GetDisplay2().GetRenderTexture2DCount()==0,"Original reduced/postprocess target ownership leaked");
#endif
    device.DestroyVolatile();device.Destroy();std::cout<<"Original ReducedRender and PostProcess managers: actual PC D24S8, quarter/sixteenth duplicate mappings, LDR/HDR primary/downsample GPU pixels, real effect user allocation with null overlap address/nonzero byte budget, read/write slots, external alias/zero-dimension rejection and teardown PASS\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
